295	    }
296	
297	    /// Seed a valid refresh token holding the legacy fixed `com.atproto.refresh`
298	    /// scope (as written before granular scopes were persisted).
299	    async fn seed_legacy_refresh_token(state: &AppState, jkt: &str) -> String {
300	        register_oauth_client(
301	            &state.db,
302	            "https://app.example.com/client-metadata.json",
