318	            "INSERT INTO oauth_tokens (id, client_id, did, scope, jkt, expires_at, created_at) \
319	             VALUES (?, ?, ?, 'com.atproto.refresh', ?, datetime('now', '+24 hours'), datetime('now'))",
320	        )
