33	    // Prune stale nonces and expired tokens on every request.
34	    cleanup_expired_state(state).await;
35	
36	    // Required fields.
37	    let refresh_token_plaintext = match form.refresh_token.as_deref() {
38	        Some(t) if !t.is_empty() => t.to_string(),
39	        _ => {
40	            return OAuthTokenError::new("invalid_request", "missing parameter: refresh_token")
41	                .into_response();
42	        }
43	    };
44	    let client_id = match form.client_id.as_deref() {
45	        Some(id) if !id.is_empty() => id.to_string(),
46	        _ => {
47	            return OAuthTokenError::new("invalid_request", "missing parameter: client_id")
48	                .into_response();
49	        }
50	    };
51	
52	    // Reject multiple DPoP headers (RFC 9449 §11.1).
53	    if headers.get_all("DPoP").iter().count() > 1 {
54	        return OAuthTokenError::new(
55	            "invalid_dpop_proof",
56	            "multiple DPoP headers are not permitted",
57	        )
58	        .into_response();
59	    }
60	
61	    // Validate DPoP proof — must be present, structurally valid, and carry a valid server nonce.
62	    let dpop_token = match headers.get("DPoP").and_then(|v| v.to_str().ok()) {
