94	            }
95	        };
96	
97	    // Hash the presented refresh token for DB lookup.
98	    let token_hash = match URL_SAFE_NO_PAD.decode(refresh_token_plaintext.as_str()) {
99	        Ok(bytes) => crate::auth::token::sha256_hex(&bytes),
100	        Err(_) => {
101	            return OAuthTokenError::new("invalid_grant", "refresh token not found or expired")
102	                .into_response();
103	        }
104	    };
105	
106	    // Retrieve the refresh token (without consuming yet).
107	    let stored = match get_oauth_refresh_token(&state.db, &token_hash).await {
108	        Ok(Some(row)) => row,
109	        Ok(None) => {
110	            return OAuthTokenError::new("invalid_grant", "refresh token not found or expired")
111	                .into_response();
112	        }
113	        Err(e) => {
114	            tracing::error!(error = %e, "failed to retrieve refresh token");
