1	// pattern: Imperative Shell
2	//
3	// The `refresh_token` grant (RFC 6749 §6 + DPoP RFC 9449): validate the DPoP proof, look up the
4	// stored refresh token, enforce the client_id match and the DPoP `jkt` binding (a NULL jkt predates
5	// binding enforcement and is rejected), then rotate — mark the old token superseded and mint a
6	// fresh DPoP-bound access token + new refresh token in the same session family, carrying the
7	// granted scope and the session's absolute expiry forward. A superseded token replayed within the
8	// short grace window is a concurrent duplicate refresh and still rotates; replayed later, it is a
9	// theft signal and the whole session family is revoked.
10	
11	use axum::{
12	    http::{HeaderMap, StatusCode},
13	    response::{IntoResponse, Response},
14	    Json,
15	};
16	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
17	
18	use super::{
19	    cleanup_expired_state, issue_access_token, token_response_headers, TokenRequestForm,
20	    TokenResponse,
21	};
22	use crate::app::AppState;
23	use crate::auth::token::generate_token;
24	use crate::auth::{issue_nonce, validate_dpop_for_token_endpoint, DpopTokenEndpointError};
25	use crate::db::oauth::{
26	    delete_oauth_refresh_session, get_oauth_refresh_token, store_rotated_oauth_refresh_token,
27	    supersede_oauth_refresh_token,
28	};
29	use crate::routes::oauth_errors::OAuthTokenError;
30	
31	pub(super) async fn handle_refresh_token(
32	    state: &AppState,
33	    headers: &HeaderMap,
34	    form: TokenRequestForm,
35	) -> Response {
36	    // Prune stale nonces and expired tokens on every request.
37	    cleanup_expired_state(state).await;
38	
39	    // Required fields.
40	    let refresh_token_plaintext = match form.refresh_token.as_deref() {
41	        Some(t) if !t.is_empty() => t.to_string(),
