/// advertises `authorization_response_iss_parameter_supported: true`, so a conformant
/// client validates `iss` on every authorization response — including error responses
/// (e.g. the user denying) — and rejects one that omits it. Error responses use the
/// same `response_mode` as a success would (a fragment-mode client only reads the
/// fragment, so a query-string error is invisible to it).
pub(super) fn error_redirect(
    redirect_uri: &str,
    error: &str,
    description: &str,
    state: &str,
    issuer: &str,
    mode: ResponseMode,
) -> Redirect {
    // Structured trace of every authorization-response error: the redirect delivers the
    // error to the client, not the operator, so without this line a failed authorize leg
    // is only a bare 3xx in the request counters. Mechanical facts only.
    tracing::info!(
        error,
        description,
        "OAuth authorization error redirect issued"
    );
    let url = format!(
        "{}{}error={}&error_description={}&state={}&iss={}",
        redirect_uri,
        mode.separator(redirect_uri),
        encode_param(error),
        encode_param(description),
        encode_param(state),
        encode_param(issuer),
    );
    Redirect::to(&url)
}

/// Render a standalone HTML error page for cases where redirecting is unsafe
/// (unknown `client_id`, mismatched `redirect_uri`).
pub(super) fn error_page(title: &str, message: &str) -> (StatusCode, Html<String>) {
    let mut html = String::with_capacity(2048);
    html.push_str(ERROR_PAGE_HEADER);
    html.push_str(&html_escape(title));
    html.push_str("</title>\n  <style>");
    html.push_str(FONT_FACES);

