36	
37	/// Form body for `POST /oauth/par` (application/x-www-form-urlencoded).
38	///
39	/// Accepts the same authorization request parameters as `GET /oauth/authorize`
40	/// so clients can push large parameter sets before sending the user to the auth endpoint.
41	#[derive(Debug, Deserialize)]
42	pub struct PARForm {
43	    pub client_id: Option<String>,
44	    pub redirect_uri: Option<String>,
45	    pub code_challenge: Option<String>,
46	    pub code_challenge_method: Option<String>,
47	    pub state: Option<String>,
48	    pub response_type: Option<String>,
49	    pub response_mode: Option<String>,
50	    pub scope: Option<String>,
51	    pub login_hint: Option<String>,
52	    /// RFC 9449 §10: the client may name its DPoP key thumbprint directly instead of (or
53	    /// as well as) sending a proof header. When both arrive they must agree.
54	    pub dpop_jkt: Option<String>,
55	}
56	
57	/// Successful PAR response body (RFC 9126 §2.2).
58	#[derive(Debug, Serialize)]
59	pub struct PARResponse {
60	    pub request_uri: String,
61	    pub expires_in: u32,
62	}
63	
64	/// OAuth 2.0 error response (RFC 6749 §5.2 / RFC 9126 §2.3).
65	struct PARError {
66	    error: &'static str,
67	    error_description: String,
68	}
69	
70	impl PARError {
71	    fn new(error: &'static str, error_description: impl Into<String>) -> Self {
72	        Self {
73	            error,
74	            error_description: error_description.into(),
75	        }
76	    }
77	}
78	
79	impl IntoResponse for PARError {
80	    fn into_response(self) -> Response {
81	        let status = if self.error == "server_error" {
82	            StatusCode::INTERNAL_SERVER_ERROR
83	        } else {
84	            StatusCode::BAD_REQUEST
85	        };
86	        (
87	            status,
88	            Json(serde_json::json!({
89	                "error": self.error,
90	                "error_description": self.error_description,
91	            })),
92	        )
93	            .into_response()
94	    }
95	}
