99	/// Resolve the DPoP key this pushed request is bound to, from a proof header, an explicit
100	/// `dpop_jkt` parameter, or both (which must then agree).
101	///
102	/// Unlike the token endpoint, a proof here is **not** required to carry a server nonce: a
103	/// PAR is typically a flow's first contact, so the client cannot hold one yet, and the proof
104	/// only asserts the client's own key rather than authorizing issuance. Requiring a nonce
105	/// here is a known interop trap (bluesky-social/atproto#3078).
106	async fn resolve_par_dpop_jkt(
107	    state: &AppState,
108	    headers: &HeaderMap,
109	    declared_jkt: Option<&str>,
110	) -> Result<Option<String>, Response> {
111	    if headers.get_all("DPoP").iter().count() > 1 {
112	        return Err(PARError::new(
113	            "invalid_dpop_proof",
114	            "multiple DPoP headers are not permitted",
115	        )
116	        .into_response());
117	    }
118	
119	    let par_url = format!(
120	        "{}/oauth/par",
121	        state.config.public_url.trim_end_matches('/')
122	    );
123	    let proven_jkt = match headers.get("DPoP").and_then(|v| v.to_str().ok()) {
124	        Some(proof) => {
125	            match crate::auth::validate_dpop_for_par(proof, "POST", &par_url).await {
126	                Ok(jkt) => Some(jkt),
127	                Err(crate::auth::DpopTokenEndpointError::InvalidProof(msg)) => {
128	                    return Err(PARError::new("invalid_dpop_proof", msg).into_response());
129	                }
130	                // `validate_dpop_for_par` never asks for a nonce and never reports a missing
131	                // header (one was present to get here).
132	                Err(_) => {
133	                    return Err(
134	                        PARError::new("invalid_dpop_proof", "DPoP proof invalid").into_response()
135	                    );
136	                }
137	            }
138	        }
139	        None => None,
140	    };
141	
142	    let declared_jkt = declared_jkt.filter(|s| !s.is_empty());
143	    match (proven_jkt, declared_jkt) {
144	        (Some(proven), Some(declared)) if proven != declared => Err(PARError::new(
145	            "invalid_request",
146	            "dpop_jkt does not match the DPoP proof's key",
147	        )
148	        .into_response()),
149	        (Some(proven), _) => Ok(Some(proven)),
150	        (None, Some(declared)) => Ok(Some(declared.to_string())),
151	        (None, None) => Ok(None),
152	    }
153	}
