167	        Some(id) => id.to_string(),
168	        None => return PARError::new("invalid_request", "client_id is required").into_response(),
169	    };
170	
171	    let redirect_uri = match form.redirect_uri.as_deref().filter(|s| !s.is_empty()) {
172	        Some(u) => u.to_string(),
173	        None => {
174	            return PARError::new("invalid_request", "redirect_uri is required").into_response()
175	        }
176	    };
177	
178	    let code_challenge = match form.code_challenge.as_deref().filter(|s| !s.is_empty()) {
179	        Some(c) => c.to_string(),
180	        None => {
181	            return PARError::new("invalid_request", "code_challenge is required").into_response()
182	        }
183	    };
184	
185	    let code_challenge_method = match form
186	        .code_challenge_method
187	        .as_deref()
188	        .filter(|s| !s.is_empty())
189	    {
190	        Some(m) => m.to_string(),
191	        None => {
192	            return PARError::new("invalid_request", "code_challenge_method is required")
193	                .into_response()
194	        }
195	    };
196	
197	    // `state` is RECOMMENDED, not required (RFC 6749 §4.1.1) and the atproto profile adds
