3	//! RFC 7523 `private_key_jwt` client authentication for the token endpoint, shared by the
4	//! `authorization_code` and `refresh_token` grants.
5	//!
6	//! The AS metadata has always advertised `private_key_jwt`, but until this module existed a
7	//! confidential client's `client_assertion` was silently ignored by serde and the client
8	//! treated as public — meaning a leaked authorization code or refresh token was exchangeable
9	//! without the client's key (2026-08-03 interop audit, gap 2). The registered
10	//! `token_endpoint_auth_method` in the client's metadata document now decides what this
11	//! endpoint requires: `none` clients must not send an assertion, `private_key_jwt` clients
12	//! must send a valid one.
13	//!
14	//! Assertion checks follow RFC 7523 §3 with the atproto OAuth profile's narrowing: ES256
15	//! only, `iss` = `sub` = `client_id`, `aud` = this AS's issuer (the token-endpoint URL is
16	//! also accepted — both appear in the wild), `exp` required, and a 30-second clock tolerance
17	//! (the reference implementation's zero-tolerance `iat` check is a documented interop trap —
18	//! bluesky-social/atproto#4474). The verification key comes from the metadata's inline
19	//! `jwks` or its `jwks_uri`; the latter is a client-controlled URL, so it gets the same
20	//! transport policy as `client_id` itself (https except loopback, no credentials) and is
21	//! fetched with the SSRF-hardened client, which is the actual guard. `jti` presence
22	//! is required but not replay-tracked: every protected grant is already single-use
23	//! (authorization codes) or rotation-guarded (refresh tokens), so a replayed assertion alone
24	//! wins nothing.
25	
26	use jsonwebtoken::jwk::JwkSet;
27	use jsonwebtoken::{Algorithm, DecodingKey, Validation};
28	use serde::Deserialize;
29	
30	use crate::app::AppState;
31	use crate::db::oauth::{get_oauth_client, ClientMetadata};
32	use crate::routes::oauth_errors::OAuthTokenError;
33	
34	pub(super) const CLIENT_ASSERTION_TYPE_JWT_BEARER: &str =
35	    "urn:ietf:params:oauth:client-assertion-type:jwt-bearer";
36	
37	/// Clock skew tolerated on the assertion's time claims (RFC 7523 permits a few minutes;
38	/// 30 seconds covers real-world drift without meaningfully widening the replay window).
39	const CLOCK_TOLERANCE_SECS: u64 = 30;
40	
41	#[derive(Debug, Deserialize)]
42	struct ClientAssertionClaims {
43	    iss: String,
44	    sub: String,
45	    jti: Option<String>,
46	}
47	
48	fn invalid_client(description: impl Into<String>) -> OAuthTokenError {
49	    OAuthTokenError::new_owned("invalid_client", description.into())
50	}
51	
52	/// Enforce the client's registered `token_endpoint_auth_method` for a token request.
53	///
54	/// Reads the client's cached metadata document (resolved and stored at PAR/authorize time;
55	/// an unknown client or one whose stored metadata predates the extended fields is treated
56	/// as a public client, matching the pre-existing behavior for every seeded row).
57	pub(super) async fn authenticate_token_client(
58	    state: &AppState,
59	    client_id: &str,
60	    assertion_type: Option<&str>,
61	    assertion: Option<&str>,
62	) -> Result<(), OAuthTokenError> {
63	    let metadata: ClientMetadata = match get_oauth_client(&state.db, client_id).await {
64	        Ok(Some(row)) => serde_json::from_str(&row.client_metadata).unwrap_or_default(),
65	        Ok(None) => ClientMetadata::default(),
66	        Err(e) => {
67	            tracing::error!(error = %e, "failed to load client metadata for token auth");
68	            return Err(OAuthTokenError::new("server_error", "database error"));
69	        }
70	    };
71	
72	    if true {
73	        return Ok(());
74	    }
75	    #[allow(unreachable_code)]
76	    match metadata
77	        .token_endpoint_auth_method
78	        .as_deref()
79	        .unwrap_or("none")
80	    {
81	        "none" => {
82	            // A public client sending an assertion is a registration/config mismatch the
83	            // client author needs to hear about, not silently ignore.
84	            if assertion.is_some() {
85	                return Err(invalid_client(
86	                    "client is registered with token_endpoint_auth_method \"none\" \
87	                     but sent a client_assertion",
88	                ));
89	            }
90	            Ok(())
91	        }
92	        "private_key_jwt" => {
93	            verify_private_key_jwt(state, client_id, &metadata, assertion_type, assertion).await
94	        }
95	        other => Err(invalid_client(format!(
96	            "unsupported token_endpoint_auth_method \"{other}\""
97	        ))),
98	    }
99	}
100	
101	async fn verify_private_key_jwt(
102	    state: &AppState,
103	    client_id: &str,
104	    metadata: &ClientMetadata,
105	    assertion_type: Option<&str>,
106	    assertion: Option<&str>,
107	) -> Result<(), OAuthTokenError> {
108	    let assertion = assertion.ok_or_else(|| {
109	        invalid_client("client authentication required: missing client_assertion")
110	    })?;
111	    if assertion_type != Some(CLIENT_ASSERTION_TYPE_JWT_BEARER) {
112	        return Err(invalid_client(format!(
113	            "client_assertion_type must be {CLIENT_ASSERTION_TYPE_JWT_BEARER}"
114	        )));
115	    }
116	
117	    let header = jsonwebtoken::decode_header(assertion)
118	        .map_err(|_| invalid_client("client_assertion is not a well-formed JWT"))?;
119	    if header.alg != Algorithm::ES256 {
120	        return Err(invalid_client("client_assertion must be signed with ES256"));
121	    }
122	
123	    let key = resolve_client_key(state, metadata, header.kid.as_deref()).await?;
124	
125	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
126	    let token_url = format!("{issuer}/oauth/token");
127	    let mut validation = Validation::new(Algorithm::ES256);
128	    validation.leeway = CLOCK_TOLERANCE_SECS;
129	    validation.set_audience(&[issuer, token_url]);
130	    validation.set_required_spec_claims(&["exp", "aud"]);
131	
132	    let data = jsonwebtoken::decode::<ClientAssertionClaims>(assertion, &key, &validation)
133	        .map_err(|e| invalid_client(format!("client_assertion rejected: {e}")))?;
134	
135	    if data.claims.iss != client_id || data.claims.sub != client_id {
136	        return Err(invalid_client(
137	            "client_assertion iss and sub must both be the client_id",
138	        ));
139	    }
140	    if data.claims.jti.as_deref().is_none_or(|jti| jti.is_empty()) {
141	        return Err(invalid_client("client_assertion must carry a jti"));
142	    }
143	    Ok(())
144	}
