146	/// Resolve the client's assertion-verification key from its metadata: the inline `jwks`
147	/// first, else a policy-checked fetch of `jwks_uri` via the SSRF-hardened client.
148	async fn resolve_client_key(
149	    state: &AppState,
150	    metadata: &ClientMetadata,
151	    kid: Option<&str>,
152	) -> Result<DecodingKey, OAuthTokenError> {
153	    if let Some(jwks) = &metadata.jwks {
154	        let set: JwkSet = serde_json::from_value(jwks.clone())
155	            .map_err(|_| invalid_client("client metadata jwks is not a valid JWK set"))?;
156	        return select_key(&set, kid);
