// The official SDK as an independent oracle.
//
// Every other file in this suite asserts what *we* concluded the protocol requires. That is
// the same reasoning that produced five production bugs: our tests agreed with our server
// because the same understanding wrote both. `@atproto/oauth-client-node` encodes Bluesky's
// reading instead, and it fails on things we would not think to assert — so its value here is
// precisely that we did not write it.
//
// Consequently this file makes almost no assertions of its own. It runs the SDK's own flow and
// lets the SDK object. A failure here usually means the server is wrong, not the test.
//
// It also exercises checks nothing else in the suite reaches: the SDK resolves the `sub` DID
// it is handed, finds that DID's PDS, and verifies the tokens really came from there — the
// check that stops a hostile authorization server minting tokens for someone else's account.
// That is why this fixture needs a directory that can answer a DID lookup (see mock-plc.ts).

import { after, before, test } from 'node:test';
import assert from 'node:assert/strict';

import { NodeOAuthClient, type NodeSavedSession, type NodeSavedState } from '@atproto/oauth-client-node';

import { approveConsent } from '../src/consent.ts';
import { startClientHost, startFixture, type ClientHost, type Fixture } from './fixture.ts';

let fixture: Fixture;
let client: ClientHost;

before(async () => {
  fixture = await startFixture();
  client = await startClientHost();
}, { timeout: 120_000 });

after(() => {
  client?.close();
  fixture?.stop();
});

/** In-memory stores — the suite is hermetic, so nothing needs to outlive the process. */
function makeStores() {
  const state = new Map<string, NodeSavedState>();
  const session = new Map<string, NodeSavedSession>();
  return {
    stateStore: {
      set: async (key: string, value: NodeSavedState) => void state.set(key, value),
      get: async (key: string) => state.get(key),
      del: async (key: string) => void state.delete(key),
    },
    sessionStore: {
      set: async (key: string, value: NodeSavedSession) => void session.set(key, value),
      get: async (key: string) => session.get(key),
      del: async (key: string) => void session.delete(key),
    },
  };
}

function makeClient(): NodeOAuthClient {
  const { stateStore, sessionStore } = makeStores();
  return new NodeOAuthClient({
    clientMetadata: {
      client_id: client.clientId,
      client_name: 'Custos OAuth conformance suite',
      redirect_uris: [client.redirectUri as `http://127.0.0.1:${string}`],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      application_type: 'web',
      token_endpoint_auth_method: 'none',
      dpop_bound_access_tokens: true,
      scope: 'atproto transition:generic',
    },
    stateStore,
    sessionStore,
    // The directory carrying this account's DID document. Without it the SDK would resolve
    // against the real plc.directory, where a hermetic test account does not exist.
    plcDirectoryUrl: fixture.plcUrl,
    // The client metadata and the directory are both plain-http loopback; the PDS itself is
    // https (the runner's throwaway CA is trusted process-wide).
    allowHttp: true,
  });
}

test('the official SDK completes a full flow against this server', async () => {
  const oauth = makeClient();

  // Passing the PDS URL rather than a handle skips handle resolution, which would need DNS
  // for a hermetic account. Everything after this point is the SDK's own implementation:
  // metadata discovery, PAR, PKCE, the DPoP nonce dance, and the token exchange.
  const authorizeUrl = await oauth.authorize(fixture.baseUrl, { scope: 'atproto transition:generic' });

  const approval = await approveConsent(fixture.baseUrl, authorizeUrl.toString(), {
    identifier: fixture.account.did,
    password: fixture.account.password,
  });
  assert.ok(approval.params.get('code'), `consent must yield a code: ${approval.location}`);

  // `callback` verifies the issuer, the state, and — via the directory — that the returned
  // DID really is hosted by the server that issued the tokens.
  const { session } = await oauth.callback(approval.params);
  assert.equal(session.did, fixture.account.did, 'the SDK must settle on the right account');

  // A request made entirely by the SDK: it signs its own DPoP proof and handles any nonce
  // challenge, so this covers the resource-server contract as the SDK understands it.
  const res = await session.fetchHandler('/xrpc/com.atproto.server.getSession', {
    method: 'GET',
  });
  assert.equal(res.status, 200, `the SDK's authenticated call must succeed: ${await res.text()}`);
  const body = (await res.json()) as { did?: string };
  assert.equal(body.did, fixture.account.did);
});

test('the official SDK can restore and refresh a session', async () => {
  // Refresh is where the SDK is strictest and where our own rotation semantics changed most,
  // so letting the SDK drive it is worth more than any assertion we would write by hand.
  const oauth = makeClient();

  const authorizeUrl = await oauth.authorize(fixture.baseUrl, { scope: 'atproto transition:generic' });
  const approval = await approveConsent(fixture.baseUrl, authorizeUrl.toString(), {
    identifier: fixture.account.did,
    password: fixture.account.password,
  });
  const { session } = await oauth.callback(approval.params);

  const restored = await oauth.restore(session.did);
  assert.equal(restored.did, session.did, 'a stored session must be restorable');

  // `getTokenSet(true)` forces a refresh rather than waiting for expiry, exercising the
  // rotation path through the SDK's own retry and locking logic.
  const refreshed = await restored.getTokenSet(true);
  assert.ok(refreshed.access_token, 'the SDK must obtain a refreshed access token');
  assert.equal(refreshed.sub, fixture.account.did, 'the refreshed token set must keep sub');

  const res = await restored.fetchHandler('/xrpc/com.atproto.server.getSession', {
    method: 'GET',
  });
  assert.equal(res.status, 200, `the refreshed session must work: ${await res.text()}`);
});

