        assert_eq!(doc["application_type"], "native");
        assert_eq!(doc["dpop_bound_access_tokens"], true);
        assert_eq!(
            doc["redirect_uris"],
            serde_json::json!(["http://127.0.0.1/", "http://[::1]/"])
        );
    }

    /// The query string is the metadata: repeated `redirect_uri` values all count, and an
