test('a code bound at PAR is redeemable only by the key that pushed the request', async () => {
  // REGRESSION: without this binding an intercepted authorization code was redeemable by
  // anyone (RFC 9449 §10). The Rust unit test writes the binding straight onto the code row;
  // only this one proves the whole chain — that a DPoP proof at PAR is what establishes it,
  // that it survives the consent leg, and that the token endpoint enforces it.
  const flowKey = await generateDpopKey();
  const attackerKey = await generateDpopKey();
  const { verifier, challenge } = pkce();

  const pushed = await par(
    metadata,
    {
      client_id: CLIENT_ID,
      redirect_uri: REDIRECT_URI,
      response_type: 'code',
      code_challenge: challenge,
      code_challenge_method: 'S256',
      scope: 'atproto',
    },
    // The proof here is what binds the flow; PAR must accept it without a server nonce,
    // since a client has none yet on its first contact.
    { dpopKey: flowKey },
  );
  assert.equal(pushed.status, 201, `a PAR carrying a DPoP proof must succeed: ${pushed.text}`);

  const approval = await approveConsent(
    fixture.baseUrl,
    `${metadata.authorization_endpoint}?client_id=${encodeURIComponent(CLIENT_ID)}` +
      `&request_uri=${encodeURIComponent(pushed.json.request_uri)}`,
    { identifier: fixture.account.did, password: fixture.account.password },
  );
  const code = approval.params.get('code');
  assert.ok(code, `consent must yield a code: ${approval.location}`);

  const params = {
    grant_type: 'authorization_code',
    code,
    redirect_uri: REDIRECT_URI,
    client_id: CLIENT_ID,
    code_verifier: verifier,
  };

  // Someone holding the intercepted code and the verifier, but not the flow's key.
  const stolen = await tokenRequestWithNonceRetry(metadata, attackerKey, params);
  assert.equal(
    stolen.final.status,
    400,
    `a code bound to another key must be refused: ${stolen.final.text}`,
  );
  assert.equal(stolen.final.json.error, 'invalid_grant');

  // The client that pushed the request still redeems it.
  const legitimate = await tokenRequestWithNonceRetry(metadata, flowKey, params);
  assert.equal(
    legitimate.final.status,
    200,
    `the key that pushed the request must still redeem the code: ${legitimate.final.text}`,
  );
  assert.equal(legitimate.final.json.sub, fixture.account.did);
});
EOF
